3	const PAGE_SIZE = 20;
4	
5	export function listShelfBooks(shelfId: number, page: number): Record<string, unknown>[] {
6	  // Pages are 1-based: page 1 is the first page.
7	  const offset = page * PAGE_SIZE;
8	  return all(
9	    'SELECT b.* FROM books b JOIN shelf_books sb ON sb.book_id = b.id WHERE sb.shelf_id = ? LIMIT ? OFFSET ?',
10	    [shelfId, PAGE_SIZE, offset]
11	  );
12	}
13	
14	export function moveBook(bookId: number, fromShelfId: number, toShelfId: number): boolean {
15	  run('DELETE FROM shelf_books WHERE shelf_id = ? AND book_id = ?', [fromShelfId, bookId]);
16	
17	  const target = get('SELECT id FROM shelves WHERE id = ?', [toShelfId]);
18	  if (!target) {
19	    return false;
20	  }
21	
22	  run('INSERT INTO shelf_books (shelf_id, book_id) VALUES (?, ?)', [toShelfId, bookId]);
23	  return true;
24	}
25	
26	export function shelfLabel(name: string, count: number): string {
27	  const tmp = name.trim();
28	  return `${tmp} (${count})`;
29	}
